"""Generate device kernels for individual BF16 eager foreach operations."""

import argparse
from pathlib import Path
from textwrap import indent

from codegen_musa_foreach import OPERATORS as MUSA_OPERATORS

ROOT = Path(__file__).resolve().parents[2] / "csrc/aten/backends"
BANNER = """\
// Copyright 2026 FlagOS Contributors
// SPDX-License-Identifier: Apache-2.0
// Generated by scripts/codegen/codegen_native_foreach.py. Do not edit.

"""

# ATen functors shared with the MUSA implementation.
OPERATORS = {
    name: (kind, fallback, 2 if ternary else 1, scalar_list, expression)
    for name, (
        kind,
        fallback,
        ternary,
        scalar_list,
        expression,
    ) in MUSA_OPERATORS.items()
}
OPERATORS.update(
    {
        "_foreach_mul_.Scalar": (
            "Multiply",
            "foreach_tensor_mul_scalar_kernel_slow_",
            0,
            False,
            "return x * alpha;",
        ),
        "_foreach_add_.Scalar": (
            "Add",
            "foreach_tensor_add_scalar_kernel_slow_",
            0,
            False,
            "return x + alpha;",
        ),
        "_foreach_div_.ScalarList": (
            "Divide",
            "foreach_tensor_div_scalarlist_kernel_slow_",
            0,
            True,
            "return x / alpha;",
        ),
        "_foreach_sqrt": (
            "Sqrt",
            "foreach_tensor_sqrt_slow",
            1,
            False,
            "return sqrtf(y);",
        ),
    }
)

HEADER = """\
#pragma once

#include <cstdint>
#include <mcr/mc_runtime_api.h>

namespace at::native::flagos::metax_foreach {

constexpr unsigned kTensorsPerBatch = 32;
constexpr unsigned kElementsPerBlock = 4096;

enum class Operation { @OPERATIONS@ };

struct Operand {
  void* result;
  const void* first;
  const void* second;
  int64_t elements;
  float scalar;
  unsigned end_block;
};

struct Batch {
  Operand operands[kTensorsPerBatch];
  unsigned count = 0;
  unsigned blocks = 0;
};

mcError_t Launch(Operation operation, const Batch& batch, mcStream_t stream);

}  // namespace at::native::flagos::metax_foreach
"""

DEVICE = """\
#include "foreach.h"

#include <mcr/mc_runtime.h>

namespace at::native::flagos::metax_foreach {
namespace {

struct alignas(16) BFloat16Vector {
  uint16_t values[8];
};

__device__ float ToFloat(uint16_t value) {
  return __uint_as_float(static_cast<uint32_t>(value) << 16);
}

__device__ uint16_t RoundBFloat16(float value) {
  const auto bits = __float_as_uint(value);
  if ((bits & 0x7fffffff) > 0x7f800000) {
    return static_cast<uint16_t>((bits >> 16) | 0x40);
  }
  return static_cast<uint16_t>((bits + 0x7fff + ((bits >> 16) & 1)) >> 16);
}

template <Operation op>
__device__ float Apply(float x, float y, float z, float alpha) {
@FORMULAS@
}

template <Operation op, int inputs>
__global__ void Pointwise(Batch batch) {
  unsigned first = 0;
  unsigned last = batch.count;
  while (last - first > 1) {
    const unsigned middle = (first + last) / 2;
    if (blockIdx.x < batch.operands[middle - 1].end_block) {
      last = middle;
    } else {
      first = middle;
    }
  }
  const auto& operand = batch.operands[first];
  const unsigned start_block = first ? batch.operands[first - 1].end_block : 0;
  const int64_t begin = static_cast<int64_t>(blockIdx.x - start_block) * kElementsPerBlock;
  const int64_t limit = begin + kElementsPerBlock;
  const int64_t end = limit < operand.elements ? limit : operand.elements;
  auto* result = static_cast<uint16_t*>(operand.result);
  const auto* a = static_cast<const uint16_t*>(operand.first);
  const auto* b = static_cast<const uint16_t*>(operand.second);
  constexpr bool in_place = op != Operation::Sqrt;
  const auto addresses = reinterpret_cast<uintptr_t>(result) |
      reinterpret_cast<uintptr_t>(a) | reinterpret_cast<uintptr_t>(b);
  if ((addresses & 15) == 0 && end % 8 == 0) {
    for (int64_t i = begin + 8 * threadIdx.x; i < end; i += 8 * blockDim.x) {
      auto* destination = reinterpret_cast<BFloat16Vector*>(result + i);
      BFloat16Vector x{}, y{}, z{};
      if constexpr (in_place) x = *destination;
      if constexpr (inputs > 0) y = *reinterpret_cast<const BFloat16Vector*>(a + i);
      if constexpr (inputs > 1) z = *reinterpret_cast<const BFloat16Vector*>(b + i);
      #pragma unroll
      for (int j = 0; j < 8; ++j) {
        x.values[j] = RoundBFloat16(Apply<op>(
            ToFloat(x.values[j]), ToFloat(y.values[j]), ToFloat(z.values[j]), operand.scalar));
      }
      *destination = x;
    }
  } else {
    for (int64_t i = begin + threadIdx.x; i < end; i += blockDim.x) {
      result[i] = RoundBFloat16(Apply<op>(
          in_place ? ToFloat(result[i]) : 0.0f,
          inputs > 0 ? ToFloat(a[i]) : 0.0f,
          inputs > 1 ? ToFloat(b[i]) : 0.0f, operand.scalar));
    }
  }
}

}  // namespace

mcError_t Launch(Operation operation, const Batch& batch, mcStream_t stream) {
  if (!batch.blocks) return mcSuccess;
  switch (operation) {
@LAUNCHES@
  }
  return mcGetLastError();
}

}  // namespace at::native::flagos::metax_foreach
"""

HOST = """\
#if defined(FLAGOS_NATIVE_METAX_VENDOR)

#include "foreach.h"
#include "../../../foreach_utils.h"
#include <flagos.h>

#include <ATen/ops/_foreach_add_native.h>
#include <ATen/ops/_foreach_addcdiv_native.h>
#include <ATen/ops/_foreach_addcmul_native.h>
#include <ATen/ops/_foreach_div_native.h>
#include <ATen/ops/_foreach_lerp_native.h>
#include <ATen/ops/_foreach_mul_native.h>
#include <ATen/ops/_foreach_sqrt_native.h>
#include <ATen/ops/empty_like.h>
#include <c10/core/DeviceGuard.h>
#include <torch/library.h>

#include <algorithm>
#include <limits>

namespace at::native::flagos::metax_foreach {
namespace {

constexpr int64_t kMaxGrid = std::numeric_limits<int>::max();

bool CanBatch(at::TensorList self, at::TensorList first = {}, at::TensorList second = {}) {
  return !self.empty() && self.front().defined() && self.front().scalar_type() == at::kBFloat16 &&
      CanBatchForeach(self, first, second, kMaxGrid * kElementsPerBlock);
}

bool Run(Operation operation, at::TensorList self, at::TensorList first,
         at::TensorList second, const at::Scalar* scalar, at::ArrayRef<at::Scalar> scalars) {
  c10::OptionalDeviceGuard guard(self.front().device());
  const auto stream = reinterpret_cast<mcStream_t>(
      GetCurrentStreamForDevice(self.front().device().index()));
  Batch batch{};
  size_t start = 0;
  auto flush = [&](size_t end) {
    const auto status = Launch(operation, batch, stream);
    if (start == 0 && (status == mcErrorNoKernelImageForDevice ||
                       status == mcErrorInvalidDeviceFunction)) {
      return false;
    }
    TORCH_CHECK(status == mcSuccess, "MACA foreach: ", mcGetErrorString(status));
    if (operation != Operation::Sqrt) {
      for (; start < end; ++start) self[start].unsafeGetTensorImpl()->bump_version();
    } else {
      start = end;
    }
    batch.count = 0;
    batch.blocks = 0;
    return true;
  };
  for (size_t i = 0; i < self.size(); ++i) {
    const int64_t elements = self[i].numel();
    if (!elements) continue;
    const int64_t blocks = (elements - 1) / kElementsPerBlock + 1;
    if ((batch.count == kTensorsPerBatch || batch.blocks + blocks > kMaxGrid) &&
        !flush(i)) return false;
    batch.blocks += static_cast<unsigned>(blocks);
    batch.operands[batch.count++] = {
        self[i].data_ptr(),
        first.empty() ? nullptr : first[i].const_data_ptr(),
        second.empty() ? nullptr : second[i].const_data_ptr(),
        elements,
        operation == Operation::Sqrt ? 0.0f : (scalar ? *scalar : scalars[i]).to<float>(),
        batch.blocks,
    };
  }
  return flush(self.size());
}

@ENTRIES@

std::vector<at::Tensor> Sqrt(at::TensorList self) {
  if (CanBatch(self)) {
    std::vector<at::Tensor> output;
    output.reserve(self.size());
    for (const auto& tensor : self) output.emplace_back(at::empty_like(tensor));
    if (Run(Operation::Sqrt, output, self, {}, nullptr, {})) return output;
  }
  return at::native::foreach_tensor_sqrt_slow(self);
}

}  // namespace
}  // namespace at::native::flagos::metax_foreach

TORCH_LIBRARY_IMPL(aten, PrivateUse1, m) {
@REGISTRATIONS@
}

#endif  // FLAGOS_NATIVE_METAX_VENDOR
"""

INPLACE = """\
void {name}(at::TensorList self{tensor_params}, {value_type} value) {{
  if ({checks} &&
      CanBatch(self, {lists}) &&
      Run(Operation::{name}, self, {lists}, {value})) {{
    return;
  }}
  at::native::{fallback}(self{tensor_args}, value);
}}
"""


def render():
    formulas, launches, entries, registrations = [], [], [], []
    for op, (name, fallback, inputs, scalar_list, expression) in OPERATORS.items():
        connector = "else " if formulas else ""
        formulas.append(
            f"  {connector}if constexpr (op == Operation::{name}) {{\n"
            + indent(expression, "    ")
            + "\n  }"
        )
        launches.append(
            f"    case Operation::{name}:\n"
            f"      Pointwise<Operation::{name}, {inputs}><<<batch.blocks, 256, 0, stream>>>(batch);\n"
            "      break;"
        )
        registrations.append(
            f'  m.impl("{op}", TORCH_FN(at::native::flagos::metax_foreach::{name}));'
        )
        if name == "Sqrt":
            continue
        tensors = ("first", "second")[:inputs]
        checks = [f"{tensor}.size() == self.size()" for tensor in tensors]
        if scalar_list:
            checks.extend(
                (
                    "value.size() == self.size()",
                    "std::none_of(value.begin(), value.end(), [](const at::Scalar& s) { return s.isComplex(); })",
                )
            )
        else:
            checks.append("!value.isComplex()")
        entries.append(
            INPLACE.format(
                name=name,
                tensor_params="".join(
                    f", at::TensorList {tensor}" for tensor in tensors
                ),
                value_type="at::ArrayRef<at::Scalar>"
                if scalar_list
                else "const at::Scalar&",
                checks=" &&\n      ".join(checks),
                lists=", ".join((*tensors, *(("{}",) * (2 - inputs)))),
                value="nullptr, value" if scalar_list else "&value, {}",
                fallback=fallback,
                tensor_args="".join(f", {tensor}" for tensor in tensors),
            )
        )
    names = ", ".join(row[0] for row in OPERATORS.values())
    return {
        "foreach.h": HEADER.replace("@OPERATIONS@", names),
        "foreach.mc": DEVICE.replace("@FORMULAS@", "\n".join(formulas)).replace(
            "@LAUNCHES@", "\n".join(launches)
        ),
        "foreach_host.cc": HOST.replace("@ENTRIES@", "\n".join(entries)).replace(
            "@REGISTRATIONS@", "\n".join(registrations)
        ),
    }


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    for vendor in ("metax", "iluvatar"):
        directory = ROOT / vendor / "generated"
        if not args.check:
            directory.mkdir(parents=True, exist_ok=True)
        for name, source in render().items():
            if vendor == "iluvatar":
                name = "foreach.ivcore" if name == "foreach.mc" else name
                for old, new in (
                    ("<mcr/mc_runtime", "<cuda_runtime"),
                    ("mcError", "cudaError"),
                    ("mcStream", "cudaStream"),
                    ("mcSuccess", "cudaSuccess"),
                    ("mcGet", "cudaGet"),
                    ("metax_foreach", "iluvatar_foreach"),
                    ("FLAGOS_NATIVE_METAX_VENDOR", "FLAGOS_NATIVE_ILUVATAR_KERNELS"),
                    ("MACA foreach", "CoreX foreach"),
                ):
                    source = source.replace(old, new)
            path = directory / name
            if args.check:
                if not path.is_file() or path.read_text() != BANNER + source:
                    raise SystemExit(f"stale generated artifact: {path}")
            else:
                path.write_text(BANNER + source)


if __name__ == "__main__":
    main()
